func readMarkdown(filename string, data []byte) (Document, error) {
	writer := newDeckWriter(filename, titleOf(filename))
	var table [][]string
	flush := func() {
		if len(table) > 0 {
			writer.table(table)
			table = nil
		}
	}
	// handle reads one line, and is told the line after it because a sentence
	// with a row of "=" under it is a heading rather than a sentence. It returns
	// whether it took that next line with it, so the caller does not read the
	// underline as a line of its own.
	var handle func(line, next string) bool
	handle = func(line, next string) bool {
		if heading, ok := atxHeading(line); ok {
			flush()
			writer.slide(heading)
			return false
		}
		if rest, quoted := withoutQuoteMarker(line); quoted {
			// A quote says where a sentence came from; it is not part of the
			// sentence. Left on, the marker reached the slide with a backslash in
			// front of it — escapeLine protects a line opening with ">" because that
			// is how the deck DSL writes a cover subtitle — so the author who quoted
			// a line got "- \> 인용입니다." for it. The marker comes off here, in the
			// reader, rather than out of escapeLine: a point opening with ">" that
			// the Word or PDF reader built out of a paragraph still has to be
			// protected, and only this reader knows the character was markup.
			//
			// Taking it off and reading the line again is what makes a quote the
			// outermost block it is in markdown: the heading, list item or table row
			// somebody wrote inside the quote is then read as that block, by the
			// cases below, with no rule of its own repeated here. The recursion ends
			// because it happens only on a line that gave up at least one ">".
			//
			// Two things it deliberately does not do. It does not join the lines of
			// one quote into a single point: the only block this reader carries
			// across lines is a table, and a second one would have to answer to
			// maximumPoints, which may have moved the earlier lines onto a "(계속)"
			// by the time the quote ends. And it does not unquote next — a "> 제목"
			// over a "> ===" is a heading this reader does not claim to read, and
			// handing the stripped line ahead to the lookahead would make next mean
			// something other than the line the caller is about to skip.
			if rest == "" {
				// A marker with nothing after it is how a quote writes a blank line,
				// and a blank line is what it is read as.
				flush()
				return false
			}
			return handle(rest, next)
		}
		switch {
		case line == "":
			flush()
		case strings.HasPrefix(line, "|"):
			cells := strings.Split(strings.Trim(line, "|"), "|")
			for index := range cells {
				cells[index] = strings.TrimSpace(cells[index])
			}
			// The |---|---| rule under a header row is punctuation, not a row.
			if isRule(cells) {
				return false
			}
			table = append(table, cells)
		case isThematicBreak(line):
			// A rule separates; it has nothing to put on a slide. flush() is here
			// because a rule ends a block at least as firmly as a blank line does,
			// and the one block this reader carries across lines is a table: two
			// tables drawn with a rule between them must not run into one grid
			// whose fourth row is another table's header.
			//
			// This case comes before the list one because "- - -" is a rule drawn
			// with the character a list is drawn with, and withoutListMarker would
			// take the leading "- " off it and leave "- -" as a point.
			flush()
		case isListLine(line):
			flush()
			point, _ := withoutListMarker(line)
			writer.point(point)
		default:
			flush()
			if underlinesHeading(next) {
				writer.slide(line)
				return true
			}
			writer.point(line)
		}
		return false
	}
	// Inside a fenced code block, a line is not markdown.
	//
	// Reading every line the same way turned a runbook's one page into several
	// slides nobody wrote: the "# 1단계" of a shell comment started a slide, the
	// ``` lines stayed as bullets, and the sentence after the block landed on the
	// slide the last line of code had made. So the block is read as the one thing
	// it is, and counted, because a deck has nothing that draws code.
	var fence string
	var held []string
	blocks, skipped := 0, 0
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	// A header the document wrote about itself is not a line of the document. It
	// is cut from the slice rather than counted past, so that the lookahead and
	// the skip flag below go on meaning what they say.
	lines = lines[frontMatterLines(lines):]
	// skip says the line coming up is the underline of the heading just written,
	// which the heading has already accounted for.
	skip := false
	for index, raw := range lines {
		line := strings.TrimSpace(raw)
		if fence == "" {
			if skip {
				skip = false
				continue
			}
			if opened := fenceOf(line); opened != "" {
				flush()
				fence = opened
				// The opening line is held with the block: if the fence turns out
				// never to close, it is a line of the document again.
				held = []string{line}
				continue
			}
			skip = handle(line, lineAfter(lines, index))
			continue
		}
		held = append(held, line)
		if closesFence(line, fence) {
			blocks++
			// The two fence lines are punctuation; what did not arrive is the
			// lines between them.
			skipped += len(held) - 2
			fence, held = "", nil
		}
	}
	if fence != "" {
		// A fence that never closes is a stray ``` somebody typed, not a block
		// that runs to the end of the file. Swallowing the rest of the document
		// on the strength of one line would lose every slide after it, so the
		// held lines are read as the lines they are — which is what this reader
		// did before it knew about fences at all.
		//
		// They are read by the same rules as the rest of the file, underlines and
		// all: a stray ``` above a heading must not change what that heading is.
		skip = false
		for index, line := range held {
			if skip {
				skip = false
				continue
			}
			skip = handle(line, lineAfter(held, index))
		}
	}
	flush()
	document, err := writer.document()
	if err != nil {
		return document, err
	}
	// Said rather than dropped, the way the Word reader says it about pictures:
	// the deck has no component that draws code, so what the block held cannot
	// arrive, and a deck that quietly comes back without the commands somebody
	// wrote their runbook around is worse than one that says so.
	//
	// The line count is there because the block count alone does not tell anybody
	// how much of their document is missing — one block is a three-line snippet
	// or forty lines of a file, and only the second is worth reopening the source
	// over. It also puts a number on the one case this reader can still get
	// wrong: if some line were ever read as a fence that the author did not mean
	// as one, the warning says how many lines went with it instead of implying a
	// snippet.
	if blocks > 0 {
		document.Warnings = append(document.Warnings, fmt.Sprintf(
			"코드 블록 %d개(%d줄)는 가져오지 않았습니다. 슬라이드에 필요한 줄은 요점으로 적어 주세요",
			blocks, skipped))
	}
	return document, nil
}

// markdownFences are the two characters a code fence is drawn with.
const markdownFences = "`~"

// withoutQuoteMarker takes the quote markers off a line and says whether there
// were any. A line that is not quoted comes back as it was.
//
// A quote inside a quote is written ">> 깊은 인용" by one editor and
// "> > 깊은 인용" by the next, and neither nesting nor the space between the
// markers means anything to a slide, so every marker comes off rather than one.
//
// What follows a marker is trimmed rather than counted. CommonMark allows the
// marker one space and treats further indent as indented code, but this reader
// has already thrown every document's indentation away by the time a line
// reaches it — prose.go trims each line before reading it — so keeping exactly
// one space here would be the only place in it where indentation meant
// anything, and it would mean it only for quoted lines.
func withoutQuoteMarker(line string) (string, bool) {
	rest, quoted := line, false
	for strings.HasPrefix(rest, ">") {
		rest = strings.TrimLeft(rest[1:], " \t")
		quoted = true
	}
	return rest, quoted
}

func isRule(cells []string) bool {
	for _, cell := range cells {
		if strings.Trim(cell, "-: ") != "" {
			return false
		}
	}
	return len(cells) > 0
}
package docs

import (
	"strings"
	"testing"
)

// A quote is markdown's outermost block: the ">" says who is speaking, not what
// is said. This reader had no case for it, so the marker travelled all the way
// to the slide — and because escapeLine protects a line opening with ">" from
// being read as the deck DSL's cover subtitle, the author who quoted a sentence
// got "- \> 인용입니다." on it: a backslash nobody typed, in front of a marker
// that was never meant to be read aloud.
//
// The expectation is the same document with the markers taken off by hand,
// rather than a string written out here, because that is what unquoting has to
// mean: the deck is the deck the author would have got had they deleted the
// markers before uploading.
func TestAQuotedSentenceIsAPointWithoutItsMarker(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte("# 제목\n\n> 인용입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	plain, err := Read("월간 보고서.md", []byte("# 제목\n\n인용입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	if document.Source != plain.Source {
		t.Errorf("read as\n%s\nwant\n%s", document.Source, plain.Source)
	}
	// A marker is punctuation that says where a sentence came from, not a
	// sentence that failed to arrive — so there is nothing to report, the same as
	// for a rule or a header.
	if len(document.Warnings) != 0 {
		t.Errorf("warned %q about a marker that lost nothing", document.Warnings)
	}
}

// A quote of several lines is several points. Running them into one would need a
// block this reader does not have — the only thing it carries across lines is a
// table — and the join would then have to answer to maximumPoints, which has
// already moved earlier points onto a "(계속)" by the time the quote ends.
func TestEachLineOfAQuoteIsItsOwnPoint(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte(
		"# 제목\n\n> 첫 문장입니다.\n> 둘째 문장입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	plain, err := Read("월간 보고서.md", []byte(
		"# 제목\n\n첫 문장입니다.\n둘째 문장입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	if document.Source != plain.Source {
		t.Errorf("read as\n%s\nwant\n%s", document.Source, plain.Source)
	}
}

// A quote inside a quote is written both ways by the editors people use, and
// neither of them is content: every marker comes off, however many there are and
// whatever space is between them.
func TestANestedQuoteLosesEveryMarker(t *testing.T) {
	plain, err := Read("월간 보고서.md", []byte("# 제목\n\n깊은 인용\n"))
	if err != nil {
		t.Fatal(err)
	}
	for _, input := range []string{
		"# 제목\n\n>> 깊은 인용\n",
		"# 제목\n\n> > 깊은 인용\n",
		"# 제목\n\n>>> 깊은 인용\n",
	} {
		document, err := Read("월간 보고서.md", []byte(input))
		if err != nil {
			t.Fatal(err)
		}
		if document.Source != plain.Source {
			t.Errorf("read %q as\n%s\nwant\n%s", input, document.Source, plain.Source)
		}
	}
}

// Unquoting is taking the marker off and reading the line again, so whatever
// block the author wrote inside the quote is the block they get: a heading names
// the slide — and the deck, and every locator under it — a list item is a point
// without a backslash in front of it, and a row of a table is a row of that
// table rather than a sentence with bars in it.
func TestABlockInsideAQuoteIsReadAsThatBlock(t *testing.T) {
	for _, document := range []struct{ quoted, plain string }{
		{"> # 분기 요약\n> 매출이 늘었습니다.\n", "# 분기 요약\n매출이 늘었습니다.\n"},
		{"# 제목\n\n> - 항목\n", "# 제목\n\n- 항목\n"},
		{
			"# 제목\n\n> | 분기 | 매출 |\n> |---|---|\n> | 1분기 | 100 |\n",
			"# 제목\n\n| 분기 | 매출 |\n|---|---|\n| 1분기 | 100 |\n",
		},
	} {
		quoted, err := Read("월간 보고서.md", []byte(document.quoted))
		if err != nil {
			t.Fatal(err)
		}
		plain, err := Read("월간 보고서.md", []byte(document.plain))
		if err != nil {
			t.Fatal(err)
		}
		if quoted.Source != plain.Source {
			t.Errorf("read %q as\n%s\nwant\n%s", document.quoted, quoted.Source, plain.Source)
		}
	}
}

// The blank line of a quote is written as a marker with nothing after it. There
// is no sentence on it to put anywhere, and it ends a block the way a blank line
// does — which is what it is.
func TestALineOfOnlyAQuoteMarkerIsNotAPoint(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte(
		"# 제목\n\n> 첫 문장입니다.\n>\n> 둘째 문장입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	plain, err := Read("월간 보고서.md", []byte(
		"# 제목\n\n첫 문장입니다.\n\n둘째 문장입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	if document.Source != plain.Source {
		t.Errorf("read as\n%s\nwant\n%s", document.Source, plain.Source)
	}
}

// What a quote is, is a line that *opens* with the marker. The same character in
// the middle of a sentence is the comparison somebody wrote, and a point that
// opens with anything else is still protected by escapeLine — including the ">"
// the Word and PDF readers can leave at the front of a paragraph, which is why
// the fix is here rather than in the escaping.
func TestAQuoteMarkerInsideASentenceIsNotAMarker(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte("# 제목\n\n매출 > 목표\n"))
	if err != nil {
		t.Fatal(err)
	}
	expected := "# 제목\n@cover\n> 월간 보고서.md\n\n" +
		"# 제목\n- 매출 > 목표\n!source 월간 보고서.md | 제목\n\n"
	if document.Source != expected {
		t.Errorf("read as\n%s\nwant\n%s", document.Source, expected)
	}
}

// Inside a fenced code block a line is not markdown, and ">" at the front of one
// is a shell prompt or a diff. It stays in the block, counted and said, rather
// than being read as a quote of the document.
func TestAQuoteInsideACodeBlockIsStillCode(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte(
		"# 제목\n\n한 문장입니다.\n\n```\n> 인용\n```\n\n끝입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	expected := "# 제목\n@cover\n> 월간 보고서.md\n\n" +
		"# 제목\n- 한 문장입니다.\n- 끝입니다.\n!source 월간 보고서.md | 제목\n\n"
	if document.Source != expected {
		t.Errorf("read as\n%s\nwant\n%s", document.Source, expected)
	}
	if len(document.Warnings) != 1 || !strings.Contains(document.Warnings[0], "코드 블록 1개(1줄)") {
		t.Errorf("warned %q, want the one block of one line", document.Warnings)
	}
}

// A fence that never closes gives its lines back to the document, read by the
// same rules as the rest of the file. One stray ``` must not be what decides
// whether a marker reaches a slide.
func TestAReplayedUnclosedFenceStillUnquotesAQuote(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte(
		"# 첫째 장\n\n```\n\n> 인용입니다.\n"))
	if err != nil {
		t.Fatal(err)
	}
	expected := "# 첫째 장\n@cover\n> 월간 보고서.md\n\n" +
		"# 첫째 장\n- ```\n- 인용입니다.\n!source 월간 보고서.md | 첫째 장\n\n"
	if document.Source != expected {
		t.Errorf("read as\n%s\nwant\n%s", document.Source, expected)
	}
	if len(document.Warnings) != 0 {
		t.Errorf("warned %q about a block the document never opened", document.Warnings)
	}
}
**프레젠테이션 → 기존 자료 가져오기**에 파일을 올립니다. 발표자료가 아니어도 됩니다.

| 올리는 것 | 되는 것 |
| --- | --- |
| `.pptx` | 제목·요점·노트·표·그림·차트(숫자째)가 넘어오고, 새 덱의 디자인으로 다시 그려집니다 |
| `.xlsx` · `.csv` · `.tsv` | 시트마다 한 장. 라벨 한 열 + 숫자 한 열이면 **차트**, 넓으면 **표**. 숨긴 시트·행·열은 화면에서 보이지 않던 대로 가져오지 않고, 뺐다고 알려 줍니다 |
| `.docx` | 제목이 슬라이드, 그 아래 문장이 요점, 표는 표 |
| `.pdf` | 한 쪽이 한 장. 첫 줄이 제목, 반복되는 머리글·꼬리글과 쪽 번호는 빼고, 출처는 몇 쪽인지 |
| `.md` · `.txt` | `#` 이 슬라이드, `-` 이 요점, 파이프 표는 표. 제목은 `# 분기 요약` 처럼 `#` **뒤에 공백**이 있을 때만이라, `#출시` 같은 해시태그나 `#1 우선순위…` 로 시작하는 문장은 그 자리의 요점으로 남습니다. `## 분기 요약 ##` 처럼 닫아 쓴 제목은 뒤의 `#` 을 떼고 `분기 요약` 이 되지만, `# C# 도입` 처럼 공백 없이 붙은 `#` 은 글자로 남습니다. `---`·`***` 같은 구분선은 슬라이드에 남지 않습니다. 맨 위에 `---` 로 감싼 YAML 머리말(`title:` 같은 메타데이터)이 있으면 그 부분도 슬라이드로 만들지 않습니다. `> 인용입니다.` 처럼 인용한 줄은 `>` 를 떼고 그 안의 내용만 남습니다 |

**각 장에 출처가 붙습니다** — `!source 매출.xlsx | 분기 실적!A1:B5` 처럼 파일과 그 안의 자리까지.
`.pdf` 는 글자가 살아 있는 파일만 읽고, 스캔본은 빈 덱을 만들지 않고 무엇이 문제인지 알려 줍니다.
가져온 뒤에는 보통 덱입니다 — 템플릿을 바꾸고, 글을 고치고, AI로 다시 쓰게 할 수 있습니다.

